<template>
  <section
    ref="desk"
    class="home"
  >
    <div
      class="home__bg"
      aria-hidden="true"
    >
      <!-- The field, sized to the screen. The browser picks by `sizes`,
           which asks for about one image pixel per CSS pixel (a soft photo
           under a shade doesn't need the screen's full density), so a phone
           gets a few hundred KB, not the 1MB original. Covering a tall page
           on a phone, it's drawn wider than the screen, hence the svh. -->
      <!-- The wallpaper (useWallpaper; Change Wallpaper in the desk's
           right-click menu). On a change the old one stays put underneath
           while the new one fades in over it, then goes, so there's always
           a photo behind (not the placeholder green and the shade). -->
      <picture
        v-if="previous"
        class="home__picture"
      >
        <source
          type="image/avif"
          :srcset="previous.avif"
          :sizes="WALLPAPER_SIZES"
        />
        <img
          class="home__photo"
          :src="previous.fallback"
          :srcset="previous.webp"
          :sizes="WALLPAPER_SIZES"
          alt=""
        />
      </picture>
      <motion.picture
        v-if="painted"
        :key="wallpaper.id"
        class="home__picture"
        :initial="previous ? { opacity: 0 } : false"
        :animate="{
          opacity: 1,
          transition: { duration: WALLPAPER_FADE_S, ease },
        }"
        @animation-complete="previous = null"
      >
        <source
          type="image/avif"
          :srcset="photo.avif"
          :sizes="WALLPAPER_SIZES"
        />
        <img
          class="home__photo"
          :src="photo.fallback"
          :srcset="photo.webp"
          :sizes="WALLPAPER_SIZES"
          alt=""
          decoding="async"
        />
      </motion.picture>
      <div class="home__shade" />
    </div>

    <p
      class="home__rail home__rail--left home__beat blush"
      style="--beat: 0; --beat-wide: 0"
    >
      *ohiosveryown*ohiosveryown*ohiosveryown*
    </p>
    <p
      class="home__rail home__rail--right home__beat blush"
      style="--beat: 0; --beat-wide: 0"
    >
      *not a portfolio of work—rather a collection of vignettes*
    </p>

    <!-- A list in the page on small screens, newest post first (see
         .home__desk); from md the desk, each where Craft puts it. -->
    <div class="home__desk">
      <DeskFile
        v-for="(study, index) in caseStudies"
        :key="study.id"
        class="home__study"
        :style="placement(study, index)"
        :name="study.label"
        :to="`/work/${study.slug}`"
        :image="study.hero?.thumb"
        :tooltip="study.tooltip?.text"
        :expanded="openStudy?.id === study.id"
        :count="countOf(study)"
        :category="study.category"
        :label="countLabel(study)"
        :delay="0.5 + postedRank(study) * 0.1"
        :sort="{
          name: study.label,
          date: dateOf(study),
          opens: countOf(study) ?? undefined,
          category: categoryRank(study),
        }"
        :ask="{
          label: study.label,
          image: study.hero?.thumb,
          kind: 'study',
          name: study.title,
          prompt: `Summarize the ${study.title} case study.`,
        }"
        @open="toggleStudy(study, $event)"
        @pointerenter="preload(study)"
        @focusin="preload(study)"
      />
      <LastPlayed />
    </div>
    <AskBar
      class="home__ask"
      data-desk-keep-out
    />
    <DeskMenu :disabled="!!openStudy" />
    <DeskDialog
      :study="openStudy"
      :origin="origin"
      @close="closeStudy"
      @ask="askFromStudy"
    />
    <NuxtPage />

    <div
      class="home__panel"
      :class="{ 'is-behind': openStudy }"
    >
      <!-- The page's h1, except while a post is open: then the post's title
           is (see DeskDialog). -->
      <component
        :is="openStudy ? 'p' : 'h1'"
        class="home__title"
        >Matthew Pence</component
      >

      <div
        class="roles"
        data-desk-keep-out
      >
