<script setup lang="ts">
  import type { CaseStudy } from '#shared/types/case-study'
  import { motion } from 'motion-v'
  import { DESK_CATEGORIES } from '~/data/deskCategories'
  import blushWoff2 from '~/assets/type/blush.woff2'

  // The background photo (see the <picture> in the template). The sizes
  // are half the slot, so about 1x on 2x screens. In public/, not imported:
  // Nuxt prefetches every asset the page's script imports, which fetched
  // all six. Cached for a year (routeRules), so a new photo needs new
  // filenames.
  // The visit's random pick, before anything below watches for changes.
  // The server can't know it, so the photo is drawn once the page is
  // running (`painted`); the pick script has it loading by then.
  const { current: wallpaper, start: startWallpaper } = useWallpaper()
  startWallpaper()
  const painted = ref(false)
  onMounted(() => (painted.value = true))
  useWallpaperRotation()
  // The first photo is the exact file the pick script painted as the
  // backdrop (one download); after a change, the usual srcset.
  const first = shallowRef(firstWallpaper())
  const photo = computed(() =>
    first.value?.id === wallpaper.value.id
      ? first.value
      : wallpaperSources(wallpaper.value),
  )
  const ease = [0.8, 0, 0.16, 1] as const
  const WALLPAPER_FADE_S = 0.8
  // The wallpaper being faded over, kept until the new one has finished
  // fading in (its animation-complete), so it never goes first. A backstop
  // a couple of seconds after the fade, in case that event never comes.
  const previous = shallowRef<ReturnType<typeof wallpaperSources> | null>(null)
  let previousTimer: ReturnType<typeof setTimeout> | undefined
  watch(
    () => wallpaper.value.id,
    (_id, before) => {
      // The first photo fades out as the file it was (not a new srcset),
      // and the backdrop's work is done.
      const old = WALLPAPERS.find((option) => option.id === before)
      previous.value =
        first.value?.id === before
          ? first.value
          : old
            ? wallpaperSources(old)
            : null
      first.value = null
      clearTimeout(previousTimer)
      previousTimer = setTimeout(
        () => (previous.value = null),
        (WALLPAPER_FADE_S + 2) * 1000,
      )
    },
  )
  onBeforeUnmount(() => clearTimeout(previousTimer))

  // iOS Safari paints the status bar, its toolbar fades, and the strip
  // under its toolbar with the html background color, never the page
  // itself (iOS 26 doesn't sample the page's content), so one color serves
  // both edges. It was teal to suit the sky at the top, but that tinted the
  // bottom over the field; dark suits the field, and the status bar is dark
  // too. On mobile `.home__shade` fades into the same color so the page end
  // has no seam. Fixed elements at the viewport edges set the color as well,
  // but turn the bar behind them opaque (tried at the top and the bottom,
  // both clipped the page under a solid band), so avoid them.
  const CHROME = '#000'

  const desk = useTemplateRef<HTMLElement>('desk')
  provideDesk(desk)

  // Arriving back at / from a panel shouldn't jump the page to the top.
  definePageMeta({
    scrollToTop: (_to, from) => !from.path.startsWith('/work/'),
  })

  const route = useRoute()
  const router = useRouter()
  const { data: caseStudies } = await useCaseStudies()

  // The URL is the source of truth: /work/[slug] opens that panel.
  // The panel follows the route (/work/[slug]), but opens and closes as soon
  // as it's asked to, not when the navigation finishes: that used to wait
  // on the route's payload, seconds when Vercel had to render it, and still
  // waits on the route's script the first time.
  // `requested` is what was asked for until the route catches up (a slug,
  // or null for closed); undefined follows the route.
  const requested = ref<string | null | undefined>(undefined)
  const openSlug = computed(() =>
    requested.value === undefined
      ? ((route.params.slug as string | undefined) ?? null)
      : requested.value,
  )
  const openStudy = computed(
    () =>
      caseStudies.value.find((study) => study.slug === openSlug.value) ?? null,
  )
  watch(
    () => route.fullPath,
    () => (requested.value = undefined),
  )
  const origin = shallowRef<HTMLElement | null>(null)

  // Every open counts, whether from an icon or a direct /work/[slug] link.
  const { counts, load: loadCounts, recordOpen } = useOpenCounts()
  watch(
    () => openStudy.value?.id,
    (id) => {
      if (id) recordOpen(id)
    },
    { immediate: true },
  )

  // null hides the pill (counts not loaded); a study nobody has opened yet
  // has no row, so it's 0.
  function countOf(study: CaseStudy) {
    return counts.value ? (counts.value[study.id] ?? 0) : null
  }

  // For Sort By ▸ Date: when it started, from the Date field ("Oct 2026",
  // "Jan 2020 – Present", "2016 – Present"); a year alone is its January.
  const MONTHS = 'jan feb mar apr may jun jul aug sep oct nov dec'.split(' ')
  function dateOf(study: CaseStudy) {
    const match = study.date?.match(/(?:([a-z]{3})[a-z]*\.?\s+)?(\d{4})/i)
    if (!match) return undefined
    const month = Math.max(0, MONTHS.indexOf(match[1]?.toLowerCase() ?? ''))
    return Date.UTC(Number(match[2]), month)
  }

  // For Sort By ▸ Label: its label's place in the key; unlabelled, last.
  function categoryRank(study: CaseStudy) {
    const rank = DESK_CATEGORIES.findIndex(
      (category) => category.id === study.category,
    )
    return rank < 0 ? undefined : rank
  }

  // The pill is decorative (aria-hidden); the icon's name carries the count.
  function countLabel(study: CaseStudy) {
    const count = countOf(study)
    if (count == null) return undefined
    return `${study.label}, opened ${count.toLocaleString()} ${count === 1 ? 'time' : 'times'}`
  }

  // Opening a panel navigates to /work/[slug], which downloads that route's
  // script first. Once the page has loaded, fetch it for every panel.
  function warmRoutes() {
    for (const study of caseStudies.value) {
      preloadRouteComponents(`/work/${study.slug}`, router)
    }
  }
  onMounted(() => {
    if (document.readyState === 'complete') warmRoutes()
    else window.addEventListener('load', warmRoutes, { once: true })
  })

  // Opening takes a second click, so warming the panel's first images on
  // hover/focus means they're usually cached by the time it opens.
  const PRELOAD_BODY_IMAGES = 2
  const preloaded = new Map<string, HTMLImageElement[]>()

  function preload(study: CaseStudy) {
    if (preloaded.has(study.id)) return
    const sources = [
      study.hero?.src,
      ...study.body
        .flatMap((node) => (node.kind === 'img' ? [node.src] : []))
        .slice(0, PRELOAD_BODY_IMAGES),
    ].filter((src): src is string => !!src)
    preloaded.set(
      study.id,
      sources.map((src) => Object.assign(new Image(), { src })),
    )
  }

  // Fallback for empty Craft positions: a loose grid in the open areas of
  // the desk, filled row by row in Order.
  const FALLBACK = { x: 10, y: 13, columns: 4, dx: 20, dy: 16 }

  function placement(study: CaseStudy, index: number) {
    const position = study.position ?? {}
    return {
      '--x': position.x ?? FALLBACK.x + (index % FALLBACK.columns) * FALLBACK.dx,
      '--y':
        position.y ??
        FALLBACK.y + Math.floor(index / FALLBACK.columns) * FALLBACK.dy,
      '--posted': postedRank(study),
    }
  }

  // Newest post first, by Published on (posts without one last); ties keep
  // their Order. The list's order on small screens, and the entrance's.
  const posted = computed(() =>
    [...caseStudies.value]
      .map((study, index) => ({ study, index }))
      .sort(
        (a, b) =>
          (b.study.publishedOn ?? '').localeCompare(a.study.publishedOn ?? '') ||
          a.index - b.index,
      )
      .map(({ study }) => study.id),
  )
  function postedRank(study: CaseStudy) {
    return posted.value.indexOf(study.id)
  }

  function toggleStudy(study: CaseStudy, from: HTMLElement | null) {
    origin.value = from
    if (openStudy.value?.id === study.id) return closeStudy()
    // Switching panels replaces the entry, so Back still closes rather than
    // stepping through every panel opened.
    const to = `/work/${study.slug}`
    const switching = !!openStudy.value
    requested.value = study.slug
    // A navigation that fails or is cancelled hands back to the route.
    return (switching ? router.replace(to) : router.push(to)).finally(
      () => (requested.value = undefined),
    )
  }

  // Back when the panel was opened from here; a direct link has nothing
  // behind it on this site, so replace instead.
  function closeStudy() {
    requested.value = null
    if (window.history.state?.back === '/') return router.back()
    return router.replace('/').finally(() => (requested.value = undefined))
  }

  // A post's "ask Mallow" button: the post closes, then Mallow answers.
  // The chat waits for the panel to finish fading out (DeskDialog's exit:
  // about half a second), so the two don't play over each other.
  const ASK_AFTER_CLOSE_MS = 500
  const { ask: askMallow } = useAskDrop()
  function askFromStudy(question: string) {
    closeStudy()
    const reduce = window.matchMedia('(prefers-reduced-motion: reduce)').matches
    setTimeout(() => askMallow(question), reduce ? 0 : ASK_AFTER_CLOSE_MS)
  }

  // The same button's link, followed from elsewhere (/?ask=…): asked once
  // on arrival, then dropped from the URL so a reload doesn't ask again.
  onMounted(() => {
    loadCounts()
    const question = route.query.ask
    if (typeof question !== 'string' || !question.trim()) return
    const { ask: _, ...query } = route.query
    router.replace({ query })
    askMallow(question.trim().slice(0, 500))
  })

  // The accent fades with the wallpaper (WALLPAPER_FADE_S). The first
  // photo's backdrop (from the pick script) is kept here too: this style
  // replaces the one the script set.
  useHead({
    htmlAttrs: {
      style: computed(() => {
        const backdrop = first.value
          ? `; --wallpaper-first: image-set(url(${first.value.avif}) type("image/avif"), url(${first.value.webp}) type("image/webp"))`
          : ''
        return `background-color: ${CHROME}; --accent: ${wallpaper.value.accent}; transition: --accent ${WALLPAPER_FADE_S}s ease${backdrop}`
      }),
    },
    meta: [{ name: 'theme-color', content: CHROME }],
    link: [
      {
        rel: 'preload',
        href: blushWoff2,
        as: 'font',
        type: 'font/woff2',
        crossorigin: 'anonymous',
      },
    ],
    // Who Matt is, for search engines (utils/structuredData). Posts add
    // their own on top. And the visit's wallpaper, picked before the first
    // paint (useWallpaper).
    script: [
      jsonLd(siteGraph(), 'ld-site'),
      { key: 'wallpaper-pick', innerHTML: wallpaperPickScript() },
    ],
  })
</script>
